(() => {
  const ID = "JotFormIFrame-262733359026055";
  const FORM_ID = "262733359026055";
  const THANKS_URL = "https://jonathan-harris.online/newsletter/thanks/";
  const ALLOWED = [
    "source", "placement", "referrer", "utm_source", "utm_medium",
    "utm_campaign", "utm_content",
  ];

  function trusted(origin) {
    try {
      const hostname = new URL(origin).hostname;
      return hostname === "jotform.com" || hostname.endsWith(".jotform.com")
        || hostname === "jotfor.ms" || hostname.endsWith(".jotfor.ms");
    } catch {
      return false;
    }
  }

  function completed(data) {
    let action = "";
    let formId = "";
    if (typeof data === "string") {
      action = data;
    } else if (data && typeof data === "object") {
      action = String(data.type || data.action || data.event || data.name || "");
      formId = String(data.formID || data.formId || "");
    }
    const isSubmit = /submission[-_ ]?completed|formSubmit|thankyou/i.test(action);
    return isSubmit && (typeof data === "string" || formId === FORM_ID);
  }

  function sourceParams() {
    const query = new URLSearchParams(location.search);
    const output = new URLSearchParams();
    for (const key of ALLOWED) {
      const value = (query.get(key) || "").trim();
      if (value) output.set(key, value.slice(0, 160));
    }
    if (!output.has("source")) output.set("source", "newsletter:direct");
    if (!output.has("placement")) output.set("placement", "newsletter-page");
    if (!output.has("referrer") && document.referrer) {
      output.set("referrer", document.referrer.slice(0, 300));
    }
    return output;
  }

  function wire() {
    const frame = document.getElementById(ID);
    if (!frame) return;
    frame.setAttribute("data-cookieyes", "ignore");
    frame.setAttribute("data-cookieconsent", "ignore");
    const base = frame.dataset.jotformBaseSrc
      || frame.getAttribute("src")
      || "https://form.jotform.com/262733359026055";
    try {
      const url = new URL(base, location.href);
      for (const [key, value] of sourceParams()) url.searchParams.set(key, value);
      frame.src = url.toString();
    } catch {}
    try {
      if (typeof window.jotformEmbedHandler === "function") {
        window.jotformEmbedHandler(
          `iframe[id='${ID}']`,
          "https://form.jotform.com/",
        );
      }
    } catch {}

    const placement = sourceParams().get("source") || "newsletter:direct";
    window.JHAnalytics?.track("newsletter_view", { placement });
    let submitted = false;
    window.addEventListener("message", (event) => {
      if (submitted || event.source !== frame.contentWindow
        || !trusted(event.origin) || !completed(event.data)) return;
      submitted = true;
      window.JHAnalytics?.track("newsletter_submit", { placement });
      window.JHAnalytics?.track("newsletter_success", { placement });
      if (placement.startsWith("ebook:") || placement.startsWith("ebook-footer:")) {
        const book_slug = placement.split(":").slice(1).join(":");
        window.JHAnalytics?.track("ebook_preview_signup", { placement, book_slug });
      }
      window.location.assign(THANKS_URL);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", wire, { once: true });
  } else {
    wire();
  }
})();
